public class CircularArraySimulator {
    public static void main(String[] args) {
        int capacity = 8; // Must be power of 2
        int mask = capacity - 1; // 7 (binary: 00000111)

        int head = 0;
        int tail = 0;

        // Simulate 10 sequential insertions and 4 deletions
        System.out.printf("%-10s | %-6s | %-6s | %-12s%n", "Action", "Head", "Tail", "Pointer Math");
        System.out.println("-".repeat(40));

        for (int i = 1; i <= 6; i++) {
            System.out.printf("Insert #%-3d | %-6d | %-6d | tail -> (%d+1)&7 = %d%n",
                              i, head, tail, tail, (tail + 1) & mask);
            tail = (tail + 1) & mask;
        }

        // Poll 3 items
        for (int i = 1; i <= 3; i++) {
            System.out.printf("Poll   #%-3d | %-6d | %-6d | head -> (%d+1)&7 = %d%n",
                              i, head, tail, head, (head + 1) & mask);
            head = (head + 1) & mask;
        }

        // Insert 4 more items (causes tail to wrap around index 0!)
        for (int i = 7; i <= 10; i++) {
            System.out.printf("Insert #%-3d | %-6d | %-6d | tail -> (%d+1)&7 = %d%n",
                              i, head, tail, tail, (tail + 1) & mask);
            tail = (tail + 1) & mask;
        }
    }
}

