public class FixedCircularQueue {
    private final int[] data = new int[4];
    private int head = 0;
    private int tail = 0;
    private int count = 0;

    public boolean enqueue(int val) {
        if (count == 4) return false;
        data[tail] = val;
        tail = (tail + 1) & 3;
        count++;
        return true;
    }

    public int dequeue() {
        if (count == 0) return -1;
        int val = data[head];
        head = (head + 1) & 3;
        count--;
        return val;
    }
}

