import java.util.ArrayDeque;

public class TokenQueueFactory {
    public static ArrayDeque<String> createQueue(String[] tokens) {
        ArrayDeque<String> deque = new ArrayDeque<>();
        if (tokens != null) {
            for (String t : tokens) {
                if (t != null) {
                    deque.offer(t);
                }
            }
        }
        return deque;
    }
}

