import java.util.ArrayDeque;

public class QueueReverser {
    public static void reverseQueue(ArrayDeque<Integer> deque) {
        if (deque == null || deque.size() <= 1) return;
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        while (!deque.isEmpty()) {
            stack.push(deque.poll());
        }
        while (!stack.isEmpty()) {
            deque.offer(stack.pop());
        }
    }
}
